#include <bits/stdc++.h>
using namespace std; int S[256];
int rkf(int k,int i,int sc){ int x=k&((1<<20)-1); if(sc==0)return (x>>(5*i))&65535; if(sc==1)return (((x<<(5*i))|(x>>(20-5*i)))&((1<<20)-1))&65535; if(sc==2)return (((x>>(5*i))|(x<<(20-5*i)))&((1<<20)-1))&65535; if(sc==3){int y=((x<<(5*i))|(x>>(20-5*i)))&((1<<20)-1);return y>>4;} if(sc==4)return (x+i*0x9e37)&65535; return (x^(i*0x9e37))&65535; }
int ff(int r,int k,int m){int a=(m&1)?r^(k&255):(r+k&255); int y=S[a]; return (m&2)?y^((k>>8)&255):(y+(k>>8)&255);}
int E(int x,int k,int sc,int m,int sw){int l=x>>8,r=x&255;for(int i=0;i<4;i++){int t=r;r=l^ff(r,rkf(k,i,sc),m);l=t;}return sw?(r<<8|l):(l<<8|r);}
int D(int x,int k,int sc,int m,int sw){int l=x>>8,r=x&255;if(sw)swap(l,r);for(int i=3;i>=0;i--){int t=l;l=r^ff(l,rkf(k,i,sc),m);r=t;}return sw?(r<<8|l):(l<<8|r);}
